-- HaatBazar PHP/MySQL schema. Import into a NEW database after backup.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(200) NOT NULL UNIQUE, phone VARCHAR(24) NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('buyer','seller','admin') NOT NULL DEFAULT 'seller', phone_verified TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS listings (id VARCHAR(80) PRIMARY KEY, user_id BIGINT UNSIGNED NULL, title VARCHAR(120) NOT NULL, category VARCHAR(100) NOT NULL, subcategory VARCHAR(120) NOT NULL, district VARCHAR(100) NOT NULL, upazila VARCHAR(100) NULL, price DECIMAL(15,2) NOT NULL, unit VARCHAR(24) NOT NULL, quantity DECIMAL(15,3) NOT NULL, negotiable TINYINT(1) NOT NULL DEFAULT 0, sellerName VARCHAR(100) NOT NULL, businessName VARCHAR(160) NOT NULL DEFAULT '', description TEXT NOT NULL, images JSON NOT NULL, phone VARCHAR(24) NOT NULL, saleType ENUM('retail','wholesale','both') NOT NULL DEFAULT 'both', minOrderQuantity DECIMAL(15,3) NOT NULL DEFAULT 1, deliveryAvailable TINYINT(1) NOT NULL DEFAULT 0, status ENUM('active','paused','sold','removed') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_listings_status_category(status,category), INDEX idx_listings_district(district)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(80) PRIMARY KEY, listing_id VARCHAR(80) NOT NULL, buyer_id BIGINT UNSIGNED NULL, quantity DECIMAL(15,3) NOT NULL, buyer_name VARCHAR(100) NOT NULL, buyer_phone VARCHAR(24) NOT NULL, buyer_email VARCHAR(200) NOT NULL DEFAULT '', address TEXT NOT NULL, amount_bdt DECIMAL(15,2) NOT NULL DEFAULT 0, status VARCHAR(40) NOT NULL DEFAULT 'pending', payment_status VARCHAR(40) NOT NULL DEFAULT 'unpaid', shipping_status VARCHAR(40) NOT NULL DEFAULT 'not_requested', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(buyer_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_orders_buyer_created(buyer_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(80) NOT NULL, listing_id VARCHAR(80) NULL, category VARCHAR(100) NULL, visitor_id VARCHAR(100) NULL, user_id BIGINT UNSIGNED NULL, metadata JSON NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_events_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS uploaded_images (name VARCHAR(255) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, content_type VARCHAR(100) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, claimed TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_uploaded_images_owner(user_id,claimed)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS marketing_settings (id TINYINT UNSIGNED PRIMARY KEY, spend_bdt DECIMAL(15,2) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO marketing_settings(id,spend_bdt) VALUES(1,0);
CREATE TABLE IF NOT EXISTS otp_challenges (id VARCHAR(80) PRIMARY KEY, phone VARCHAR(24) NOT NULL, purpose ENUM('verify_phone','password_reset') NOT NULL, code_hash VARCHAR(255) NOT NULL, expires_at BIGINT NOT NULL, attempts INT UNSIGNED NOT NULL DEFAULT 0, consumed TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_otp_phone_purpose(phone,purpose,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS seller_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, business_name VARCHAR(160) NOT NULL, nid_last4 CHAR(4) NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', reviewer_note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_transactions (id VARCHAR(80) PRIMARY KEY, order_id VARCHAR(80) NOT NULL, provider VARCHAR(80) NOT NULL, requested_method VARCHAR(80) NOT NULL, gateway_transaction_id VARCHAR(160) NOT NULL UNIQUE, gateway_val_id VARCHAR(160) NULL, amount_bdt DECIMAL(15,2) NOT NULL, status ENUM('initiated','pending','paid','failed','cancelled') NOT NULL DEFAULT 'initiated', gateway_payload JSON NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), INDEX idx_payment_order(order_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS courier_shipments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(80) NOT NULL UNIQUE, provider VARCHAR(80) NOT NULL, consignment_id VARCHAR(160) NULL, tracking_code VARCHAR(160) NULL, status VARCHAR(40) NOT NULL DEFAULT 'requested', response_json JSON NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(80) NOT NULL, old_status VARCHAR(40) NULL, new_status VARCHAR(40) NOT NULL, actor_user_id BIGINT UNSIGNED NULL, note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_order_history_order(order_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
